  impact: { en: ['impact', 'sustainab', 'social', 'environment', 'esg', 'sdg', 'society', 'climate', 'jobs'], pt: ['impacto', 'sustentab', 'social', 'ambiente', 'esg', 'ods', 'sociedade', 'clima', 'emprego'] },
